select '開館30周年記念 ジョルジュ・ルオー ―いつくしむまなざし、祈りの筆あと', v.name, v.id, v.location, date '2026-09-19', date '2026-12-06',
       jsonb_build_object('summary', '開館30周年記念企画展。同館所蔵のルオー作品全4点に、パナソニック汐留美術館の所蔵作品約35点を加え、敬虔なカトリック教徒だったジョルジュ・ルオーが聖俗両方の主題にあらわした祈りを浮き彫りにする。'), 'https://www.asahigroup-oyamazaki.com/exhibition/rouault/'
