with candidate (n, title, artist, image_url, content) as (
    values
    (1, '雪中の狩人', 'ピーテル・ブリューゲル（父）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Pieter_Bruegel_the_Elder_-_Hunters_in_the_Snow_%28Winter%29_-_Google_Art_Project.jpg/960px-Pieter_Bruegel_the_Elder_-_Hunters_in_the_Snow_%28Winter%29_-_Google_Art_Project.jpg', '1565年に描かれた油彩の板絵で、ウィーン美術史美術館が所蔵しています。季節ごとの暮らしを描いた連作の一枚で、連作のうち5点が今に伝わります。手前では、狐一匹だけを提げた狩人たちが犬を連れて雪の丘を戻ってきます。左の宿屋では火をたいて豚の毛を焼く人々、木々にはカラス、谷の凍った池ではスケートや球遊びを楽しむ小さな人影。冬の村の一日が、高い視点から一望に収められています。'),
    (2, '雪松図屏風', '円山応挙', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Okyo_Pines_right.jpg/960px-Okyo_Pines_right.jpg', '円山応挙が描いた六曲一双の屏風で、国宝に指定され、三井記念美術館が所蔵しています。京都・大坂・江戸で呉服商と両替店を営んだ三井家の依頼で描かれたと考えられています。紙の白をそのまま雪として生かし、松葉を少しずつ濃い墨で描き重ねることで、雪をかぶった松の姿を表しました。輪郭線を使わない描き方と、足元に掃かれた金泥にも注目すると、雪に反射する冬の光が感じられます。')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, display_date)
select f.title, f.artist, f.image_url, f.content, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url)
values ('モネ《アイリス》約88億円で落札、仏国内最高額', 'サザビーズ・パリでモネ晩年の大作《アイリス》が5000万ユーロで落札。フランス国内の美術品オークション史上最高額に。', 'サザビーズが10月22日にパリで開催した「シュルンベルジェ・コレクション」セールで、クロード・モネの晩年の大作《アイリス》（1924-25頃）が5000万ユーロ（約88億円）で落札された。フランス国内の美術品オークション史上最高額となる。予想価格は2200万〜3000万ユーロで、6人の入札者が約45分競り合い、アジアの個人コレクターの代理が電話で落札した。同作はジヴェルニーの庭園を描いた約20点の連作のひとつ。モネ作品4点の落札総額は約6650万ユーロ、セール全体は7440万ユーロ（約131億円）で、サザビーズ・パリの単一セール史上最高額となった。', '', '作品・作家', 'https://bijutsutecho.com/magazine/news/market/33247')
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url)
values ('都内39館が一斉夜間開館、11月に初開催', '「ARTE TOKYO × NIGHT MUSEUM」が11月6日と20日に初開催。国立西洋美術館や東博など39館が参加する。', '東京都内の39の美術館・博物館が参加する一斉夜間開館プログラム「ARTE TOKYO × NIGHT MUSEUM」が、11月6日と20日に初めて開催される。東京都と東京国際文化芸術祭実行委員会が主催する文化芸術祭「ARTE TOKYO」の特別企画。国立西洋美術館、東京国立博物館、東京都現代美術館、国立新美術館、森美術館などが参加し、24館が両日、9館が6日、6館が20日に参加する。一部施設では「100万人のクラシックライブ」と連携したミニコンサートや、都立文化施設での「Museum × Music！」も実施。開館時間や料金は施設ごとに異なる。', '', '美術館', 'https://bijutsutecho.com/magazine/news/headline/33241')
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url)
values ('石上純也が「バラガン賞」初代受賞者に', 'ボッテガ・ヴェネタとラ・クアドラが創設した国際建築賞の初代受賞者に建築家・石上純也が選ばれた。', '建築家・石上純也が、ボッテガ・ヴェネタとメキシコの文化施設「La Cuadra（ラ・クアドラ）」が共同で創設した国際建築賞「The Barragán Prize（バラガン賞）」の初代受賞者に選ばれた。同賞はメキシコ人建築家として唯一プリツカー賞を受賞したルイス・バラガンの名を冠した年次賞。第1回授賞式は10月9日、バラガンが1960年代後半に手がけた「La Cuadra」で開かれた。石上は2004年に事務所を設立し、「神奈川工科大学KAIT工房」「水庭」などで知られる。2010年にはヴェネチア・ビエンナーレ国際建築展で金獅子賞を受賞している。', '', '作品・作家', 'https://bijutsutecho.com/magazine/news/headline/33179')
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url)
values ('愛知県美術館でビゲロー没後100年展', 'ボストン美術館の日本美術コレクションの礎を築いたビゲローの「幻のコレクション」を紹介。10月30日開幕。', '愛知県美術館で「ビゲロー 幻のコレクションと近代日本画の夜明け──日本美術に魅せられたボストン人──」展が10月30日〜12月13日に開催される。ボストン美術館の日本美術コレクションの礎を築いたウィリアム・ビゲロー（1850〜1926）の没後100年記念展。アメリカへ渡ったのちに昭和初期の日本で競売にかけられた作品群に焦点を当て、喜多川歌麿《太夫と禿図》などを展示する。狩野芳崖の重要文化財《不動明王》（前期）や《悲母観音》（12月1日〜13日）、橋本雅邦らの名品も公開し、「鑑画会」唯一の女性画家・前田錦楓にも注目する。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33157')
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url)
values ('北斎館50周年、ナント展の凱旋展開催', '小布施の北斎館で、仏ナントで約15万人を動員した北斎展の凱旋展。所蔵の約160点を一挙公開する。', '長野県小布施町の北斎館で、開館50周年を記念した「フランス ナント『EXPOSITION HOKUSAI』凱旋展 小布施 北斎の傑作」が10月24日〜2027年1月17日に開催される。2025年にフランス・ナントのブルターニュ公爵城で開かれ約15万人を動員した展覧会の凱旋展で、同館所蔵の約160点の北斎コレクションを一挙公開する。「冨嶽三十六景」「諸国名橋奇覧」「諸国滝廻」などの連作のほか、「宗理」時代の役者絵や摺物、《柳下傘持美人》などの肉筆画も並ぶ。ナント市やブルターニュ公爵城の歴史を紹介する展示も予定されている。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33156')
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ママ、パパが怪我をした！', 'Mama, Papa is Wounded!', 'イヴ・タンギー', 'Yves Tanguy',
        1927,
        (select slug from public.art_movements where slug = 'surrealism'),
        'ニューヨーク近代美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/Mama%2C_Papa_is_Wounded%21.jpg/960px-Mama%2C_Papa_is_Wounded%21.jpg', '美術の教育を受けていなかったタンギーは、デ・キリコの《子供の脳》を見て画家になることを決め、1924年ごろ友人プレヴェールを通じてブルトンを中心とするシュルレアリスムの仲間に加わりました。1927年のこの作品は、デ・キリコから受け継いだものをよく示すタンギーの代表作の一つとされます。限られた色数で描いた果てしない風景に、角ばったものや有機的な抽象の形を置く描き方は、デ・キリコの謎めいた空間を受け継ぎながら、具体的な物を描かない夢の風景へと進めたものでした。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('肝臓は雄鶏のとさか', 'The Liver Is the Cock''s Comb', 'アーシル・ゴーキー', 'Arshile Gorky',
        1944,
        (select slug from public.art_movements where slug = 'abstract-expressionism'),
        'バッファローAKG美術館（旧オルブライト＝ノックス美術館）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/The_Liver_is_the_Cock%27s_Comb_y_Arshile_Gorky%2C_1944.jpg/960px-The_Liver_is_the_Cock%27s_Comb_y_Arshile_Gorky%2C_1944.jpg', 'セザンヌやピカソの影響を抜け出したゴーキーが、自分の様式にたどり着いた頂点とされる大作です。この絵を見たブルトンは「アメリカで描かれた最も重要な絵の一つ」と呼び、ゴーキーをシュルレアリストと認め、作品は1947年にパリで開かれたシュルレアリスム展にも出品されました。のびやかで即興的な筆づかいは、シュルレアリスムとの出会いを経て、のちのニューヨーク派の抽象表現主義を先取りしたものです。1948年に亡くなったゴーキーの影響は、次の世代の画家たちに認められています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;
